using System; using System.Collections.Generic; using System.Linq; using Avalonia; using Avalonia.Controls; using Avalonia.Layout; using Avalonia.Media; using Kreta.Core; using Kreta.Contexts; public class TantargyiAtlagokView_0c3b2a1f4d5e : UserControl, IEvolView { public string Name => "Tantárgyi Átlagaim"; public string Description => "A jegyeid átlagának megtekintése tantárgyankénti bontásban."; private readonly IStudentContext? _context; public TantargyiAtlagokView_0c3b2a1f4d5e() { } public TantargyiAtlagokView_0c3b2a1f4d5e(IStudentContext context) { _context = context; } public Control CreateView() { var panel = new StackPanel { Spacing = 15, Margin = new Thickness(20) }; var title = new TextBlock { Text = "Átlagaim tantárgyanként", FontSize = 22, FontWeight = FontWeight.Bold, HorizontalAlignment = HorizontalAlignment.Center }; panel.Children.Add(title); if (_context == null) { panel.Children.Add(new TextBlock { Text = "Hiba: A diák kontextus nem érhető el.", Foreground = Brushes.Red, HorizontalAlignment = HorizontalAlignment.Center }); return panel; } var myGrades = _context.GetMyGrades(); if (myGrades == null || !myGrades.Any()) { panel.Children.Add(new TextBlock { Text = "Nincsenek még rögzített jegyeid.", HorizontalAlignment = HorizontalAlignment.Center, Margin = new Thickness(0, 20, 0, 0) }); return panel; } var averageBySubject = myGrades .Where(g => g.Subject != null) .GroupBy(g => g.Subject.Name) .Select(group => new { SubjectName = group.Key, Average = group.Average(g => g.Value) }) .OrderBy(s => s.SubjectName) .ToList(); var resultsListBox = new ListBox { ItemsSource = averageBySubject.Select(a => $"{a.SubjectName}: {a.Average:F2}").ToList() }; panel.Children.Add(new Border { Margin = new Thickness(0, 10, 0, 0), BorderBrush = Brushes.Gray, BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(5), Child = resultsListBox }); return panel; } }